268→export async function stageStructuredIntegration(repoRoot, taskId, resultSha, opts = {}) {
269→  ensureBatonExcluded(repoRoot);
270→  if (!isClean(repoRoot)) throw mergeError('structured integration requires a clean main checkout', 'structured_main_dirty');
271→  let rightSha;
272→  try { rightSha = sh('git', ['rev-parse', '--verify', `${resultSha}^{commit}`], repoRoot); }
273→  catch (error) { throw mergeError('structured integration result is not a commit', 'structured_invalid_result', error); }
274→  const beforeSha = sh('git', ['rev-parse', 'HEAD'], repoRoot);
275→  try { sh('git', ['merge-base', '--is-ancestor', rightSha, beforeSha], repoRoot); throw mergeError('structured integration result is already contained by main', 'structured_already_integrated'); }
276→  catch (error) { if (error?.code === 'structured_already_integrated') throw error; }
277→  const mergeBaseSha = sh('git', ['merge-base', beforeSha, rightSha], repoRoot);
278→  const root = integrationRoot(repoRoot); mkdirSync(root, { recursive: true });
279→  const stagePath = join(root, `${taskId}-${randomBytes(4).toString('hex')}`);
280→  try { sh('git', ['worktree', 'add', '--detach', stagePath, beforeSha], repoRoot); }
281→  catch (error) { throw mergeError('structured integration stage could not be created', 'structured_stage_failed', error); }
282→  const classes = []; const resolutions = [];
283→  try {
284→    let mergeClean = true;
285→    try { gitFile(['-c', 'core.hooksPath=/dev/null', '-c', 'merge.conflictStyle=diff3', 'merge', '--no-verify', '--no-commit', '--no-ff', rightSha], stagePath, { encoding: 'utf8', stdio: 'pipe' }); }
286→    catch { mergeClean = false; }
287→    const unmergedRaw = gitFile(['diff', '--name-only', '--diff-filter=U', '-z'], stagePath, { encoding: 'utf8' });
288→    const conflictedPaths = unmergedRaw.split('\0').filter(Boolean);
289→    if (mergeClean) classes.push({ path: null, class: 'clean_textual' });
290→    else {
291→      if (conflictedPaths.length === 0) throw mergeError('Git merge failed without resolvable text conflicts', 'structured_merge_failed');
292→      if (!opts.resolver || typeof opts.resolver.resolve !== 'function') throw mergeError('structured merge resolver is unavailable', 'structured_tool_unavailable');
293→      if (!Number.isSafeInteger(opts.resolver.maxFileBytes) || opts.resolver.maxFileBytes <= 0) throw mergeError('structured resolver lacks a deployment-derived file ceiling', 'structured_policy_invalid');
294→      for (const relativePath of conflictedPaths) {
295→        const absolutePath = pathResolve(stagePath, relativePath); const within = pathRelative(stagePath, absolutePath);
296→        if (within === '..' || within.startsWith(`..${sep}`) || isAbsolute(within) || !existsSync(absolutePath) || !lstatSync(absolutePath).isFile()) throw mergeError(`unsupported structured conflict path: ${relativePath}`, 'structured_unsupported_path');
297→        const conflict = readFileSync(absolutePath); if (conflict.includes(0)) throw mergeError(`structured conflict is binary: ${relativePath}`, 'structured_binary_conflict');
298→        if (conflict.byteLength > opts.resolver.maxFileBytes) throw mergeError(`structured conflict exceeds file budget: ${relativePath}`, 'structured_file_too_large');
299→        const isolatedRoot = realpathSync(mkdtempSync(join(tmpdir(), 'baton-structured-conflict-'))); const isolatedName = basename(relativePath); const isolatedPath = join(isolatedRoot, isolatedName);
300→        let resolution; let merged;
