146→  const fences = new FenceTable();
147→  const router = new AdaptiveRouter({ mode: 'adaptive', now });
148→  const story = new StoryCompiler({ now });
149→  const runtimeScopes = opts.runtimeScopes ?? new RuntimeIsolation({
150→    repoRoot: opts.repoRoot,
151→    ...(opts.runtimeIsolation ?? {}),
152→  });
153→  const coordination = opts.coordination ?? new CoordinationStore(join(opts.logDir, 'coordination'), {
154→    operationalRead: (worker, seq) => log.read(worker, seq).find((event) => event.seq === seq) ?? null,
155→  });
156→  const publisher = Object.hasOwn(opts, 'publisher') ? opts.publisher : async ({ remote, ref, sha }) => {
157→    execFileSync('git', ['push', '--porcelain', remote, `${sha}:${ref}`], { cwd: opts.repoRoot, stdio: 'ignore' });
158→    return { transport: 'git-push' };
159→  };
160→
161→  // C2/D5: real selection via router.pick(task, candidates) over the ceiling-feasible
162→  // set — no first-fit fallback. `pick()` already returns null when nothing is eligible,
163→  // which is exactly "queue" (the coordinator's own ceiling re-check catches it too).
164→  const route = (task, cards, inFlight) => {
165→    // `cards` is already the coordinator's exact model/effort/session/policy-filtered
166→    // candidate set. Re-expanding from every registered adapter would resurrect rejected
167→    // candidates and dereference absent cards in heterogeneous fleets.
168→    let feasible = Object.keys(cards).filter((v) => (inFlight[v] ?? 0) < cards[v].concurrencyCeiling);
169→    // SC7: the explicit capability tag beats operator folklore — when any feasible card lists
170→    // the task's taskType in nonRefuserFor, restrict to those vendors. Feasibility is computed
171→    // FIRST (a capable-but-saturated vendor never restricts) and an unlisted taskType leaves
172→    // the pool untouched — the restriction can never strand a task.
173→    const capable = feasible.filter((v) => Array.isArray(cards[v].nonRefuserFor) && cards[v].nonRefuserFor.includes(task.taskType));
174→    if (capable.length > 0) feasible = capable;
175→    const candidateKey = (v) => {
176→      return routeTupleKey(cards[v], cards[v].modelSelection?.resolved, cards[v].modelSelection?.resolvedEffort, task.taskType);
177→    };
178→    const candidates = feasible.map((v) => ({
179→      modelVersion: candidateKey(v),
180→      // Read-only migration aliases for router state written before the full
181→      // harness/model/effort tuple became the canonical learning identity.
182→      legacyModelVersions: [
183→        ...(cards[v].modelSelection?.resolved
184→          ? [`${cards[v].harness}@${cards[v].version}#${cards[v].modelSelection.resolved}`]
185→          : []),
186→        `${cards[v].harness}@${cards[v].version}`,
187→      ],
188→      family: cards[v].modelSelection?.family ?? 'default',
189→      concurrencyCeiling: cards[v].concurrencyCeiling,
190→      inFlight: inFlight[v] ?? 0,
191→    }));
192→    const chosen = router.pick(task, candidates);
193→    if (!chosen) return null;
194→    // First-listed feasible vendor wins a modelVersion collision: two adapters CAN share
195→    // harness@version (e.g. one-shot ClaudeCli and session ClaudeSessionCli for the same CLI),
196→    // and a last-wins Map would silently flip which vendor key receives the dispatch.
197→    return feasible.find((v) => candidateKey(v) === chosen) ?? null;
198→  };
199→  route.record = (mv, tt, win) => router.record(mv, tt, win);
