206→      verifyDependencyDirs: opts.verifyDependencyDirs,
207→      structuredMerge: opts.structuredMerge,
208→    }),
209→    runtimeScopes,
210→    coordination,
211→    repoRoot: opts.repoRoot,
212→    referee: refereeFn,
213→    route,
214→    accept: (verdict, acceptOpts) => accept(verdict, acceptOpts),
215→    acceptOpts: {
216→      requireRedGreen: opts.requireRedGreen ?? false,
217→      requireCoverage: opts.requireCoverage ?? false,
218→      requireMutation: opts.requireMutation ?? false,
219→    },

