462→export async function reconcile(repoRoot, expectedActiveTaskIds = [], opts = {}) {
463→  const report = { prunedAdminEntries: [], removedZombieDirs: [], removedIntegrationDirs: [], errors: [] };
464→  try {
465→    sh('git', ['worktree', 'prune'], repoRoot);
466→  } catch (err) {
467→    report.errors.push(`prune: ${err.message || err}`);
468→  }
469→
470→  // Structured integration is never resumed after coordinator restart: without an in-memory
471→  // operation holding the freshly observed verification verdict, a candidate is evidence only.
472→  // Reap every detached stage and require a new attempt to reconstruct and reverify it.
473→  const mergeRoot = integrationRoot(repoRoot);
474→  if (existsSync(mergeRoot)) {
475→    for (const entry of readdirSync(mergeRoot)) {
476→      const fullDir = join(mergeRoot, entry);
477→      let isDir = false; try { isDir = statSync(fullDir).isDirectory(); } catch { continue; }
478→      if (!isDir) continue;
479→      try {
480→        try { sh('git', ['worktree', 'remove', '--force', fullDir], repoRoot); }
481→        catch { rmSync(fullDir, { recursive: true, force: true }); }
482→        report.removedIntegrationDirs.push(fullDir);
483→        logEvent(opts, entry, 'worktree.integration_reconciled', { dir: fullDir });
484→      } catch (err) { report.errors.push(`${entry}: ${err.message || err}`); }
485→    }
486→    try { if (readdirSync(mergeRoot).length === 0) rmSync(mergeRoot, { recursive: true, force: true }); } catch { /* best effort */ }
487→  }
488→
489→  const expected = new Set(expectedActiveTaskIds);
490→
491→  const wtRoot = join(repoRoot, '.baton', 'wt');
492→  if (existsSync(wtRoot)) {
493→    for (const entry of readdirSync(wtRoot)) {
494→      if (entry.endsWith('.meta.json')) continue;
495→      const fullDir = join(wtRoot, entry);
496→      let isDir = false;
497→      try { isDir = statSync(fullDir).isDirectory(); } catch { continue; }
498→      if (!isDir) continue;
499→      if (expected.has(entry)) continue;
500→      try {
501→        try {
502→          sh('git', ['worktree', 'remove', '--force', fullDir], repoRoot);
503→        } catch {
504→          rmSync(fullDir, { recursive: true, force: true });
505→        }
506→        const metaFile = metaPathFor(repoRoot, entry);
507→        if (existsSync(metaFile)) rmSync(metaFile, { force: true });
508→        report.removedZombieDirs.push(fullDir);
509→        logEvent(opts, entry, 'worktree.reconciled', { dir: fullDir });
510→      } catch (err) {
511→        report.errors.push(`${entry}: ${err.message || err}`);
512→      }
513→    }
514→  }
515→
516→  // Note: `.baton/verify/*` sandboxes are intentionally NOT swept here. They are always
517→  // created and reaped synchronously by their own caller (referee/coordinator via
518→  // `sandbox.cleanup()`) within the same operation, so they never need boot-time zombie
519→  // detection, and sweeping them here would misattribute reconcile events away from the
520→  // taskId-scoped `worker` field callers rely on (red workers-trust#9).
521→  try { sh('git', ['worktree', 'prune'], repoRoot); } catch { /* best-effort */ }
522→  return report;
523→}
