66→test('SM6: clean structured resolution is freshly verified before main moves', async () => {
67→  const root = repo(); let calls = 0; let isolatedCwd = null;
68→  const resolver = {
69→    maxFileBytes: 4096,
70→    identity: () => ({ tool: 'fake-mergiraf', version: 'test' }),
71→    resolve: async ({ cwd, relativePath, absolutePath }) => { calls += 1; isolatedCwd = cwd; assert.equal(relativePath, 'value.js'); writeFileSync(absolutePath, 'export const values = { alpha: 2, beta: 3 };\n'); return { status: 'resolved' }; },
72→  };
73→  const { coordinator, log, handle } = await accepted(root, 'sm-success', 'export const values = { alpha: 2 };\n', resolver);
74→  write(root, 'src/value.js', 'export const values = { alpha: 1, beta: 3 };\n'); commit(root, 'main adds beta'); const before = git(['rev-parse', 'HEAD'], root);
75→  const result = await coordinator.integrate(handle.id, { strategy: 'structured', actor: 'test' });
76→  assert.equal(calls, 1); assert.equal(result.integration.beforeSha, before); assert.equal(result.integration.afterSha, git(['rev-parse', 'HEAD'], root));
77→  assert.equal(isolatedCwd.includes('baton-structured-conflict-'), true); assert.equal(isolatedCwd.startsWith(root), false);
78→  assert.equal(result.integration.stageSha, result.integration.afterSha); assert.equal(result.integration.strategy, 'structured');
79→  assert.equal(result.integration.verdict.reverified, true); assert.equal(result.integration.verdict.passed, true);
